/* The reference side of the bit-exact test (core/tests/test_quad_bitexact.c): ChoralRoot's FM TONE AS IT IS at
 * v0.25.1, compiled from the tag's own tree (tools/Makefile: `git archive v0.25.1` into tools/build/cr-v0.25.1, its
 * felucca_tables.h generated by the tag's tools/gen_tables.py), driven by ChoralRoot's own host-test voice driver
 * (tests/cr_quad_test.c drv_reset / drv_patch4 / drv_on / drv_tick, copied here with its arithmetic unchanged) and
 * its fade steal (voice.c: voice_kill, then env_tick's stage 4 renders one block with m.amp1 = 0 and ends the voice).
 * Built with -I<tag>/firmware/src -I<tag>/build/gen; nothing of QUADRILLE is included. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define __attribute__(x)
#define FELUCCA_QUAD 1
#include "felucca_tables.h"
#include "core.h"
#include "dsp.c"
#include "eng_quad.c"

#include "bitexact.h"

static void drv_reset(track_t *t, int bpm)
{
    memset(t, 0, sizeof *t);
    memset(quad_vs, 0, sizeof quad_vs);
    memset(quad_lfo, 0, sizeof quad_lfo);
    t->p[P_VOICE] = V_POLY;
    t->eng_req = t->engine = ENGI_QUAD;
    song.g[G_BPM] = (int16_t)bpm;
}
static void drv_patch4(track_t *t, const int16_t *p)
{
    memcpy(quad_patch[quad_tr(t)], p, QP_NP * sizeof(int16_t));
    quad_macros_out(t);
}
static void drv_on(track_t *t, uint32_t i, uint32_t note, uint32_t vel)
{
    voice_t *v = &t->v[i];
    int sounding = v->active;
    v->note = (uint8_t)note;
    v->vel = v->mvel = (uint8_t)vel;
    v->gate = v->active = 1;
    v->stage = 1;
    v->age = i + 1u;
    v->pitch16 = v->pitch_cur = (int32_t)note * 16;
    t->m_vi = (uint8_t)i;
    if (!sounding)
        v->env = v->env_out = 0;
    quad_note_on(t, v);
}
/* drv_tick for the part (block, then each voice: done, then render); a voice given up (stage 4, voice.c voice_kill)
 * renders its block ramped to 0 and ends (voice.c env_tick stage 4 and track_render_x's ownenv path) */
static uint32_t drv_tick(track_t *t, int32_t *out)
{
    uint32_t i, nr = 0;
    memset(out, 0, CTL * sizeof *out);
    quad_block(t);
    for (i = 0; i < NVOICE; i++) {
        voice_t *v = &t->v[i];
        vmod_t m;
        int killed;
        if (!v->active)
            continue;
        killed = v->stage == 4u;
        if (!killed && quad_done(t, v)) {
            v->active = v->gate = 0;
            v->env = v->env_out = 0;
            continue;
        }
        v->env = 1 << 24;
        memset(&m, 0, sizeof m);
        m.amp0 = v->env_out;
        m.amp1 = v->env_out = killed ? 0 : 32767;
        m.pitch16 = v->pitch_cur;
        m.inc = pitch_inc((uint32_t)m.pitch16);
        m.shape = 64 << 8;
        quad_render(t, v, out, CTL, &m);
        if (killed) {
            v->active = v->gate = 0;
            v->stage = 0;
            v->env = v->env_out = 0;
        }
        nr++;
    }
    return nr;
}

static void patch_of(int k, int16_t *p)
{
    if (k <= 0)
        quad_init_patch(p);
    else
        quad_preset_patch((uint32_t)k - 1u, p);
}

int cr_ref_npresets(void) { return 1 + (int)QUAD_NPRESETS; }
const char *cr_ref_preset_name(int k) { return k <= 0 ? "INIT" : QUAD_PRESETS[k - 1].name; }
void cr_ref_preset_patch(int k, int16_t *p) { patch_of(k, p); }

uint32_t cr_ref_render(int preset, const be_scen_t *sc, int32_t *out, uint32_t max)
{
    static track_t *t;
    int16_t p[QP_NP];
    uint32_t b, n = 0, vi = sc->vidx;
    t = &trk[0];
    drv_reset(t, sc->bpm);
    patch_of(preset, p);
    drv_patch4(t, p);
    drv_on(t, vi, sc->note, sc->vel);
    for (b = 0; n + CTL <= max; b++) {
        if (b == sc->hold)
            t->v[vi].gate = 0;
        if (sc->again_at && b == sc->again_at)
            drv_on(t, vi, sc->again_note, sc->again_vel);
        if (sc->again_at && b == sc->again_at + sc->hold)
            t->v[vi].gate = 0;
        if (sc->kill_at && b == sc->kill_at) {         /* voice.c voice_kill */
            t->v[vi].gate = 0;
            t->v[vi].stage = 4;
        }
        if (!drv_tick(t, out + n))
            break;
        n += CTL;
    }
    return n;
}
